WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_cal_b_forward'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '起止日期推算', 'kp-cal-b-forward', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "星期日期计算基础"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心常识：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "平年 365 天（52周余1天），闰年 366 天（52周余2天）。大月 31，小月 30。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、核心口诀：余数即为推移天数"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "过一个平年，星期几往后推 1 天。过一个闰年，星期几往后推 2 天。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、闰年判定法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "四年一闰，百年不闰，四百年再闰。末尾两位不能整除 4 的绝对是平年。"}]}]}$$ AS jsonb), NULL, '起止日期推算的核心考点与实战推导。', category_node.id, CAST('["数量关系", "起止日期推算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_cal_b_forward", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
